# The Edlio family (edjobs::fetch_edlio_postings(), edjobs 0.22.0, 2026-11-14;
# claude-notes/2026-11-14_small-families/edlio/): each registry row, with its own Job_Link, City and
# k12_list_rules.csv rule, against the district's captured page(s). Expected titles are the routine's output,
# checked against each district's old parser (every difference listed in the README).
# Test titles name the parser and the district so the auto-fix issue finds that district's fixtures.
# Generated by claude-notes/2026-11-14_small-families/edlio/make_family_test.R.

edlio_parse <- function(district, fixture) {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  row <- reg[reg$District == district, ]
  expect_equal(nrow(row), 1)
  expect_equal(row$Platform, "Edlio")
  rules <- read_k12_list_rules(here::here("k12_list_rules.csv"))
  html <- paste(readLines(fixture, warn = FALSE, encoding = "UTF-8"), collapse = "\n")
  r <- parse_edlio_postings(html, row$Job_Link, row$City, k12_list_rule(rules, district, "List_Start"),
                                  k12_list_rule(rules, district, "List_Stop"), k12_list_rule(rules, district, "Skip_Section"))
  expect_true(all(r$Location == row$City))
  r
}

test_that("parse_edlio_postings: Livingston Public Schools", {
  r <- edlio_parse("Livingston Public Schools", test_path("fixtures", "livingston_employment.html"))
  expect_equal(r$Title, c("PHS Custodian 2026 (2)",
      "PHS Head Cheer Coach 26 27",
      "Head Boys Basketball Coach 26 27",
      "PHS Assistant Volleyball Coaches 2026",
      "PHS Assistant Boys Basketball Coach 26 27",
      "PHS Assistant Football Coach 2026 27",
      "PHS Assistant Boys Soccer Coach 26 27 - Copy",
      "PHS Math Teacher",
      "PHS Counselor WBL Coordinator",
      "PHS BPA Advisor 2026 27",
      "PHS HOSA Advisor 2026 27",
      "SGMS Paraeducators 2026 27",
      "SGMS Volleyball Coach 26 27",
      "LEAP Program High Needs Paraeducator",
      "New Chapter High Needs Paraeducator 26 27",
      "After School Activity Coordinator",
      "After School Program Aide",
      "Relief Bus Driver 2025",
      "Dish Server Cashiers",
      "Food Service Cook"))
})

