test_that("every Edlio registry row resolves to the family routine", {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  for (d in reg$District[reg$Platform == "Edlio"]) expect_equal(edjobs::resolve_scraper_call(d)$fn, "fetch_edlio_postings", info = d)
  expect_equal(edjobs::resolve_scraper_call("Livingston Public Schools")$fn, "fetch_edlio_postings")
})
